import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1787777736000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Four environment variables; the full reference table is at <a href="/reference/environment">Reference → Environment variables</a>.</p><h2 id="the-url" tabindex="-1">The URL <a class="header-anchor" href="#the-url" aria-label="Permalink to “The URL”">​</a></h2><p><code>CALIBRE_WEB_URL</code> is the <strong>root of the web UI</strong> — the <code>/opds</code> path is appended automatically:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CALIBRE_WEB_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">https://books.example.com</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">        # right</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CALIBRE_WEB_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">https://books.example.com/opds</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">   # wrong</span></span></code></pre></div><p>Subpath installations work: Calibre-Web emits hrefs that include its script root, so <code>https://host.example/calibre</code> resolves correctly.</p><p>Rules the server enforces at startup:</p><ul><li>A URL that does not parse, uses a non-http(s) scheme, or <strong>contains embedded credentials</strong> (<code>https://user:pass@host</code>) is fatal — credentials belong in their own variables, never in a URL that ends up in logs.</li><li>Plain <code>http://</code> to a non-loopback host only warns, but means the password crosses the network unencrypted. Use HTTPS.</li></ul><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to “Credentials”">​</a></h2><p><code>CALIBRE_WEB_USERNAME</code> and <code>CALIBRE_WEB_PASSWORD</code> are the <strong>web login</strong> of a Calibre-Web account — Calibre-Web has no separate API tokens. They count as a pair:</p><ul><li>both set → HTTP Basic auth on every request</li><li>both unset → anonymous mode, for instances that allow anonymous browsing</li><li>only one set → configuration error, reported on every call</li></ul><p>The password is deleted from <code>process.env</code> immediately after being read, so child processes and environment dumps do not see it.</p><h2 id="self-signed-certificates" tabindex="-1">Self-signed certificates <a class="header-anchor" href="#self-signed-certificates" aria-label="Permalink to “Self-signed certificates”">​</a></h2><p><code>CALIBRE_WEB_INSECURE_TLS=true</code> accepts an invalid certificate — but only for requests that go to the configured host, via a scoped TLS dispatcher. It never sets <code>NODE_TLS_REJECT_UNAUTHORIZED</code>, so certificate validation for anything else in the process stays intact.</p><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to “Pagination”">​</a></h2><p>Feeds are paginated by the instance&#39;s <strong>Books per page</strong> setting (default 60); the page size is not client-controllable. Every listing returns a <code>pagination</code> object — when <code>hasMore</code> is true, pass <code>nextOffset</code> as the <code>offset</code> of the next call. The value is read from the feed&#39;s own <code>rel=&quot;next&quot;</code> link, never computed.</p><p>Two exceptions:</p><ul><li><code>list_books</code> with <code>view: &quot;discover&quot;</code> is a random selection and not paginated.</li><li><code>search_books</code> is not paginated server-side at all: Calibre-Web returns every match in one response. The tool caps the result client-side (<code>limit</code>, default 50, max 200) and reports the real match count in <code>totalFound</code>.</li></ul><h2 id="response-budgets" tabindex="-1">Response budgets <a class="header-anchor" href="#response-budgets" aria-label="Permalink to “Response budgets”">​</a></h2><p>Everything that reaches the model is bounded:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Limit</th></tr></thead><tbody><tr><td>Feed body</td><td>8 MB, refused while streaming</td></tr><tr><td>Cover image</td><td>1 MB (Calibre-Web serves the full-size cover on this route)</td></tr><tr><td>Summary per book</td><td>1 000 characters</td></tr><tr><td>Summaries per response</td><td>30 000 characters shared budget</td></tr><tr><td>Any single tool result</td><td>400 000 characters hard backstop</td></tr></tbody></table><p>Whenever a budget trims something, the result says so in <code>notes</code>.</p><h2 id="choosing-the-tools-that-load" tabindex="-1">Choosing the tools that load <a class="header-anchor" href="#choosing-the-tools-that-load" aria-label="Permalink to “Choosing the tools that load”">​</a></h2><p>Not every session needs every tool. <code>CALIBRE_WEB_ALLOW_TOOLS</code> and <code>CALIBRE_WEB_DENY_TOOLS</code> let you draw your own:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CALIBRE_WEB_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">essential</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CALIBRE_WEB_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">search_books,list_shelves</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CALIBRE_WEB_DENY_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">get_cover</span></span></code></pre></div><p>Why bother, when all six work: a model chooses the right tool far more reliably from a handful than from a long list, and every tool it can see costs context on every single request. If this is the only MCP server in a session, six is fine. If it is one of six, it is not.</p><p><strong>The syntax.</strong> Comma-separated entries. An entry is either an exact tool name or a prefix with a trailing <code>*</code> — <code>list_*</code> matches every tool whose name starts with <code>list_</code>. Entries are trimmed and case-insensitive, empty ones are ignored, and an empty value counts as unset. Nothing else is a pattern: <code>*_x</code> and <code>list_*_x</code> are rejected rather than silently matching nothing.</p><p><strong><code>essential</code></strong> is a curated preset of five:</p><p><code>search_books</code>, <code>list_books</code>, <code>list_shelves</code>, <code>get_shelf_books</code>, <code>get_stats</code>.</p><p>It composes — naming a tool alongside it puts that one back, and <code>CALIBRE_WEB_DENY_TOOLS</code> takes one away.</p><p><strong>Both together.</strong> <code>CALIBRE_WEB_ALLOW_TOOLS</code> decides what is in; <code>CALIBRE_WEB_DENY_TOOLS</code> is then subtracted from the result. With only a deny list, everything else stays.</p><p><strong>A name that matches nothing stops the server</strong>, with the offending entry and the list of real names. That is deliberate: the alternative is a tool quietly missing from <code>tools/list</code>, and nobody traces an absence back to an environment variable. The same applies to a pattern that matches no tool.</p>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};